import subprocess, numpy as np, sys

def grab(t, w=1280, h=720):
    cmd=["ffmpeg","-v","error","-ss",str(t),"-i","/workspace/materials/flight.mp4",
         "-frames:v","1","-f","rawvideo","-pix_fmt","rgb24","-"]
    raw=subprocess.run(cmd,capture_output=True).stdout
    return np.frombuffer(raw,np.uint8).reshape(h,w,3)

def save_png(arr, path):
    h,w=arr.shape[:2]
    p=subprocess.run(["ffmpeg","-v","error","-y","-f","rawvideo","-pix_fmt","rgb24",
        "-s",f"{w}x{h}","-i","-","-frames:v","1",path],input=arr.astype(np.uint8).tobytes())

# altimeter center full-frame ~ (724,393). crop box half-size
def crop_alt(img, cx=724, cy=393, r=70):
    return img[cy-r:cy+r, cx-r:cx+r]

def upscale(a, f=2):
    return np.repeat(np.repeat(a,f,0),f,1)

def montage(times, cols=6, gauge='alt', scale=2, label=True):
    crops=[]
    for t in times:
        img=grab(t)
        if gauge=='alt':
            c=crop_alt(img)
        elif gauge=='asi':
            c=crop_alt(img, cx=520, cy=393)  # ASI center approx
        elif gauge=='hdg':
            c=crop_alt(img, cx=622, cy=504)
        c=upscale(c, scale)
        # draw a small label bar (white) - we can't draw text easily; rely on grid order
        crops.append(c)
    ch,cw=crops[0].shape[:2]
    rows=(len(crops)+cols-1)//cols
    canvas=np.zeros((rows*ch, cols*cw, 3),np.uint8)
    for i,c in enumerate(crops):
        r,cc=divmod(i,cols)
        canvas[r*ch:(r+1)*ch, cc*cw:(cc+1)*cw]=c
    return canvas

if __name__=="__main__":
    # test: find gauge centers by dumping one full frame region
    img=grab(5)
    save_png(img[345:555, 470:776], "fullsix_t5.png")
    print("saved fullsix")

